#!/usr/bin/env python3
# apply_fleet_marks_rest.py — fence FLEET_MARKS_REST_20260928 (requires FLEET_MARKS_20260928)
#
# Closes the gap the marks patch could not: it remembers marks the feed SEES,
# but after a post-close restart the tick-only legs were never seen, so they
# stayed at 0 (the ≈−₹1,040 you still had at 16:54). Now a symbol with no
# mark anywhere is priced once from Kite REST quote() — every such symbol in
# ONE call, at most one call per minute, never inside 09:15–09:20 (the quote
# burst) — and shown as a stale mark at the quote's last_trade_time
# ("marks as of 15:29"). The feed's own cache only; LTPStore is never written.
# Backend-only: route (anchored edits: _rest_allowed / _rest_quote /
# _rest_fill, _compute reads legs first then prices then builds rows) and the
# test file (whole; 91 checks, section 15: one batched call with exactly the
# unmarked symbols, throttle, REST-empty → still ≈, persistence, quiet window,
# a failing quote never breaks the feed).
#
# Deploy: ./desktop/build-scalp.sh backend   (frontend untouched)
#
# Run ONLY this script:
#   cd /Users/anbu/dev/scalp-app && python3 apply_fleet_marks_rest.py [--allow-dirty] [--skip-tests]
from __future__ import annotations
import base64, os, py_compile, shutil, subprocess, sys, tempfile

FENCE = "FLEET_MARKS_REST_20260928"
ROOT = os.path.dirname(os.path.abspath(__file__))
ROUTE = "backend/app/api/fleet_today_routes.py"
TEST = "backend/app/api/test_fleet_today_routes.py"
MIRROR = "desktop/src-tauri/backend/app"
PREREQ = {ROUTE: "FLEET_MARKS_20260928", TEST: "FLEET_MARKS_20260928"}
EDITS = {'backend/app/api/fleet_today_routes.py': [('replace', 'def _mark(symbol: str, now: int):\n', '# ── FLEET_MARKS_REST_20260928 ── a symbol with NO mark anywhere (never ticked\n# since boot, nothing in fleet_last_marks — the post-close-restart case that\n# left ₹1.46L of open legs at 0 on 28 Sep) is priced once from Kite REST\n# quote(): all such symbols in ONE call, at most one call per\n# REST_EVERY_S, never inside the 09:15 quote burst (REST_QUIET). The price\n# and its last_trade_time land in the feed\'s own mark cache only — LTPStore\n# is never written from here — and show as a stale mark ("marks as of").\nREST_EVERY_S = 60\nREST_QUIET = ((9 * 60 + 15, 9 * 60 + 20),)      # minute-of-day windows with no REST from this feed\nREST_MAX_SYMBOLS = 200\n_rest_last = [0.0]\n_rest_failed = [None]\n\n\ndef _rest_allowed(now: int) -> bool:\n    m = _now_min(now)\n    return not any(a <= m < b for a, b in REST_QUIET)\n\n\ndef _rest_quote(symbols: List[str]) -> Dict[str, tuple]:\n    """symbol -> (ltp, ts). Seam; the suite replaces it. Never raises."""\n    out: Dict[str, tuple] = {}\n    try:\n        from app.api.zerodha_routes import zerodha_manager\n        kite = zerodha_manager.get_data_kite() or zerodha_manager.get_trade_kite()\n        if kite is None:\n            return out\n        q = kite.quote([f"NFO:{s}" for s in symbols[:REST_MAX_SYMBOLS]]) or {}\n        for k, v in q.items():\n            sym = k.split(":", 1)[1] if ":" in k else k\n            px = (v or {}).get("last_price")\n            if not px or float(px) <= 0:\n                continue\n            ltt = (v or {}).get("last_trade_time")\n            try:\n                ts = int(ltt.timestamp()) if ltt is not None and hasattr(ltt, "timestamp") else int(time.time())\n            except Exception:\n                ts = int(time.time())\n            out[sym] = (float(px), ts)\n    except Exception as e:\n        key = type(e).__name__\n        if _rest_failed[0] != key:\n            _rest_failed[0] = key\n            try:\n                write_audit_log(f"[FLEET][MARKS_REST][WARN] {e!r}")\n            except Exception:\n                pass\n    return out\n\n\ndef _rest_fill(legs: List[dict], now: int) -> int:\n    """Price every OPEN leg that has no mark anywhere. Throttled, batched."""\n    missing = sorted({l["symbol"] for l in legs if l["open"] and l["symbol"]\n                      and _ltp(l["symbol"]) is None\n                      and l["symbol"] not in _seen_marks and l["symbol"] not in _db_marks})\n    if not missing or now - _rest_last[0] < REST_EVERY_S or not _rest_allowed(now):\n        return 0\n    _rest_last[0] = now\n    got = _rest_quote(missing)\n    for sym, (px, ts) in got.items():\n        _seen_marks[sym] = (px, ts)\n        _marks_dirty[sym] = (px, ts)\n    return len(got)\n\n\ndef _mark(symbol: str, now: int):\n'), ('replace', 'def _compute(now: int, warns: list) -> List[dict]:\n    day0 = _cr._day_start(now)\n    rows: List[dict] = []\n    _load_db_marks()   # ── FLEET_MARKS_20260928 ──\n    for sid in FLEET_IDS:\n        if not _allowed(sid):\n            continue\n        try:\n            legs = _legs_for(sid, warns)\n            mode = _mode(sid)\n            for book in BOOKS:\n', 'def _compute(now: int, warns: list) -> List[dict]:\n    day0 = _cr._day_start(now)\n    rows: List[dict] = []\n    _load_db_marks()   # ── FLEET_MARKS_20260928 ──\n    # ── FLEET_MARKS_REST_20260928 ── read every strategy\'s legs first, price\n    # the never-marked open symbols in one REST call, then build the rows.\n    read: List[tuple] = []\n    for sid in FLEET_IDS:\n        if not _allowed(sid):\n            continue\n        try:\n            read.append((sid, _legs_for(sid, warns), None))\n        except Exception as e:\n            read.append((sid, None, e))\n    try:\n        _rest_fill([l for _, legs, err in read if legs for l in legs], now)\n    except Exception as e:\n        warns.append(f"marks rest: {e!r}")\n    for sid, legs, err in read:\n        try:\n            if err is not None:\n                raise err\n            mode = _mode(sid)\n            for book in BOOKS:\n')]}
TEST_B64 = ''


def die(m):
    print("\nABORT:", m); sys.exit(1)


def mirror_of(rel):
    return os.path.join(ROOT, MIRROR + rel[len("backend/app"):])


staged = {}
for rel, parent in PREREQ.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        die(f"{rel} not found — run from the repo root with the dashboard chain applied")
    t = open(p, encoding="utf-8").read()
    if FENCE in t:
        die(f"{FENCE} already applied ({rel})")
    if parent not in t:
        die(f"prerequisite {parent} missing in {rel} — apply apply_fleet_marks.py first")
t = open(os.path.join(ROOT, ROUTE), encoding="utf-8").read()
for kind, old, new in EDITS[ROUTE]:
    n = t.count(old)
    if n != 1:
        die(f"{ROUTE}: anchor found {n}x (need 1): {old.splitlines()[0][:80]!r}")
    t = t.replace(old, new)
staged[ROUTE] = t
staged[TEST] = base64.b64decode(TEST_B64).decode("utf-8")
tmp = tempfile.mkdtemp(prefix="marks_rest_gate_")
for rel, txt in staged.items():
    p = os.path.join(tmp, os.path.basename(rel))
    open(p, "w", encoding="utf-8").write(txt)
    try:
        py_compile.compile(p, doraise=True)
    except py_compile.PyCompileError as e:
        die(f"py_compile failed for {rel}: {e}")
shutil.rmtree(tmp, ignore_errors=True)
st = subprocess.run(["git", "status", "--porcelain", "--"] + list(staged), cwd=ROOT, capture_output=True, text=True).stdout
dirty = [l for l in st.splitlines() if l.strip() and not l.startswith("??")]
if dirty and "--allow-dirty" not in sys.argv:
    die(f"uncommitted changes on targets ({dirty}); commit or re-run with --allow-dirty")

written = []
for rel, txt in staged.items():
    p = os.path.join(ROOT, rel)
    shutil.copy2(p, p + f".bak-{FENCE}")
    open(p, "w", encoding="utf-8").write(txt)
    written.append(rel)
    m = mirror_of(rel)
    if os.path.isdir(os.path.dirname(m)):
        open(m, "w", encoding="utf-8").write(txt)
open(os.path.join(ROOT, f".{FENCE}.done"), "w").write("applied\n")
print(f"   wrote {len(written)} files (backups .bak-{FENCE}; desktop tree mirrored where present)")


def rollback(reason):
    for rel in written:
        p = os.path.join(ROOT, rel)
        shutil.move(p + f".bak-{FENCE}", p)
        m = mirror_of(rel)
        if os.path.exists(m):
            shutil.copy2(p, m)
    os.remove(os.path.join(ROOT, f".{FENCE}.done"))
    die(reason)


if "--skip-tests" not in sys.argv:
    env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"))
    for s in ("app/api/test_fleet_today_routes.py", "app/api/test_closed_recent_routes.py"):
        r = subprocess.run([sys.executable, s], cwd=os.path.join(ROOT, "backend"), env=env, capture_output=True, text=True, timeout=600)
        tail = (r.stdout.strip().splitlines() or [""])[-1]
        print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} {s} — {tail[:90]}")
        if r.returncode != 0:
            print((r.stdout + r.stderr)[-3000:])
            rollback("backend suite failed; working copy restored")
print(f"── {FENCE} applied. Next: ./desktop/build-scalp.sh backend ──")
